package com.justjava.humanresource.employeeexit.workflow.delegate; import com.justjava.humanresource.employeeexit.service.EmployeeExitService; import lombok.RequiredArgsConstructor; import org.flowable.engine.delegate.*; import org.springframework.stereotype.Component;
@Component("applyExitApprovalDecisionDelegate") @RequiredArgsConstructor public class ApplyExitApprovalDecisionDelegate implements JavaDelegate {private final EmployeeExitService service;public void execute(DelegateExecution e){boolean more=service.applyApprovalDecision(((Number)e.getVariable("exitCaseId")).longValue(),String.valueOf(e.getVariable("exitDecision")),number(e.getVariable("exitActorId")),(String)e.getVariable("exitComment"),(String)e.getVariable("flowableTaskId"));e.setVariable("hasMoreExitApprovers",more);if(more){int index=((Number)e.getVariable("currentApprovalIndex")).intValue()+1;e.setVariable("currentApprovalIndex",index);java.util.List<?> ids=(java.util.List<?>)e.getVariable("approverIds");e.setVariable("currentApproverId",ids.get(index).toString());}}private Long number(Object v){return v==null?null:Long.valueOf(v.toString());}}
